package validations

// UpdateModuleAutomationBody es el cuerpo del PATCH del módulo de
// automatizaciones. El handler lo decodifica con `DisallowUnknownFields` (el
// equivalente del `.strict()` de zod: una clave desconocida es un 400) y luego
// vuelve a decodificar el MISMO cuerpo crudo como `map[string]any`, que es lo
// que el repositorio mezcla con `mongo.MergeDeepJSON` por PRESENCIA de clave.
//
// Igual que en el resto de módulos, el PATCH NO expone `schema_version` ni
// `updated_at`: los estampa el repositorio en cada escritura. `enabled_since`
// tampoco, porque es WRITE-ONCE del servidor.
//
// AVISO sobre `automations`: el merge SUSTITUYE los arrays enteros, no los
// fusiona. Es justo lo que hace falta —así se puede BORRAR una automatización
// mandando la lista sin ella—, pero implica que quien escriba tiene que enviar
// la lista COMPLETA. Un PATCH con una sola automatización borra las demás.
//
// La forma de cada automatización NO se valida aquí. Quien la valida es el
// catálogo compartido (`@kena/shared/automation`) en las dos puntas: la
// dashboard antes de dejar publicar y el módulo antes de ejecutar. Repetir esas
// reglas en Go sería una tercera copia que se separaría de las otras dos, y la
// que peor se detecta: el documento se guardaría igual.
type UpdateModuleAutomationBody struct {
	Enabled          *bool             `json:"enabled,omitempty"`
	Automations      *[]map[string]any `json:"automations,omitempty"`
	LogChannelID     *string           `json:"log_channel_id,omitempty"`
	MaxActionsPerRun *int              `json:"max_actions_per_run,omitempty"`
}

import * as z from "zod";

// Tipos DB inlined. La versión publicada de `@kena/shared` (0.0.1 en el
// registry) todavía no incluye el módulo tempvoice en su dist — hasta que se
// republique, la fuente de verdad es
// `libraries/library-shared/src/db/schemas/DBGuildSchemas.ts` del monorepo.
// Mantener en sync con `DBModuleTempVoice` / `DBTempVoiceCreator`.
// `updated_at` (Date) lo gestiona el backend; se omite en el dashboard.
export interface DBTempVoiceCreator {
  /** Nombre del creador EN EL DASHBOARD (etiqueta de su fila plegable). No se ve
   * en Discord — para el nombre de los canales está `name_template`. */
  name: string;
  /** Canal de voz "join-to-create". */
  channel_id: string;
  /** Categoría donde nacen los canales temporales. `null` = misma que el creador. */
  parent_id: string | null;
  /** Plantilla del nombre. Vars: {user}, {user_id}, {counter} ({count} = alias
   * oculto de {counter}). Vacío = usa el default. */
  name_template: string;
  /** Límite de usuarios (0 = ilimitado). */
  user_limit: number;
  /** Bitrate en bps. */
  bitrate: number;
  /** Nace bloqueado (deniega Connect a @everyone). */
  locked: boolean;
  /** Canal de texto opcional para el panel persistente. `null` = panel efímero en el chat del propio canal de voz. */
  panel_channel_id: string | null;
  /** Si al crear un canal de este creador se publica el panel de control. `false` = el canal nace sin panel. */
  panel_enabled: boolean;
  /** Si el canal temporal tiene chat de texto integrado. */
  text_chat_enabled: boolean;
  /** Región RTC con la que nacen los canales (ver RTC_REGIONS). `null`/"auto" = automática. */
  rtc_region: string | null;
  /** Roles con control total permanente sobre los canales de este creador. Vacío = ninguno. */
  moderator_role_ids: string[];
  /** Acciones DESHABILITADAS en los canales de este creador. Se comprueba ANTES que el
   * acceso por roles/canales de `commands`: aunque el usuario tenga permiso para el
   * comando, si su creador deniega la acción no se ejecuta (y el botón del panel
   * correspondiente ni se pinta).
   *
   * Es una lista de DENEGADAS (no de permitidas) a propósito: vacío = nada bloqueado =
   * comportamiento previo al campo, y las acciones nuevas nacen permitidas. */
  denied_actions: TempVoiceAction[];
  /** Panel de control PROPIO de este creador. `null` = usa el panel global del módulo
   * (`DBModuleTempVoice.panel`). Si no es `null` lo sustituye por completo (textos +
   * botones) en los canales nacidos de este creador. */
  panel_override: DBTempVoicePanel | null;
}

// Regiones RTC de Discord. ⚠️ Debe coincidir con `RTC_REGIONS` del módulo
// (`modules/tempvoice-module/src/shared/constants.ts`). `auto` = automática.
export const RTC_REGIONS = [
  { value: "auto", label: "Automática" },
  { value: "rotterdam", label: "Europa (Rotterdam)" },
  { value: "madrid", label: "Europa (Madrid)" },
  { value: "london", label: "Europa (Londres)" },
  { value: "frankfurt", label: "Europa (Fráncfort)" },
  { value: "us-east", label: "EE. UU. Este" },
  { value: "us-west", label: "EE. UU. Oeste" },
  { value: "us-central", label: "EE. UU. Central" },
  { value: "us-south", label: "EE. UU. Sur" },
  { value: "brazil", label: "Brasil" },
  { value: "sydney", label: "Sídney" },
  { value: "singapore", label: "Singapur" },
  { value: "japan", label: "Japón" },
  { value: "india", label: "India" },
  { value: "southafrica", label: "Sudáfrica" },
] as const;

export interface DBTempVoiceDefaults {
  user_limit: number;
  bitrate: number;
  locked: boolean;
  name_template: string;
}

/**
 * Modo de una lista de acceso: `only` = whitelist (solo estos ids pueden),
 * `all_except` = blacklist (todos pueden excepto estos ids).
 */
export interface DBAccessList {
  mode: "only" | "all_except";
  ids: string[];
}

/** Acceso de un comando: listas independientes para roles, canales y categorías. */
export interface DBCommandAccess {
  roles: DBAccessList;
  channels: DBAccessList;
  /** Categorías (canales GuildCategory): se matchea el `parent_id` del canal donde se invoca. */
  categories: DBAccessList;
}

/**
 * Sincronización POR EJE de un comando con el acceso global. Cada lista
 * (roles/canales/categorías) decide de forma independiente si hereda el global
 * (`true`) o usa el acceso propio del comando (`false`). Espejo de
 * `DBTempVoiceCommandSync` del backend.
 */
export interface DBTempVoiceCommandSync {
  roles: boolean;
  channels: boolean;
  categories: boolean;
}

/**
 * Config por comando. `use_global` sincroniza cada eje con el acceso global
 * (`commands_global`) de forma independiente; un eje en `false` usa su
 * `access.<eje>` propio. Espejo de `DBTempVoiceCommand` del backend.
 */
export interface DBConfigurableCommand {
  enabled: boolean;
  use_global: DBTempVoiceCommandSync;
  access: DBCommandAccess;
}

// Comandos del panel de canales temporales. El orden fija la UI.
export const TEMPVOICE_COMMANDS = [
  "name",
  "limit",
  "bitrate",
  "region",
  "lock",
  "unlock",
  "permit",
  "reject",
  "kick",
  "transfer",
  "claim",
  "panel",
  "info",
] as const;
export type TempVoiceCommand = (typeof TEMPVOICE_COMMANDS)[number];

/**
 * Acciones que un creador puede DENEGAR (`DBTempVoiceCreator.denied_actions`).
 * Coincide 1:1 con los subcomandos `/voice` y con las acciones asignables a un
 * botón del panel, así que denegar una acción la corta en AMBAS superficies.
 *
 * ⚠️ Debe coincidir con `TEMPVOICE_ACTIONS` de library-shared.
 */
export const TEMPVOICE_ACTIONS = [
  "name",
  "limit",
  "bitrate",
  "region",
  "lock",
  "unlock",
  "permit",
  "reject",
  "kick",
  "transfer",
  "claim",
  "trust",
  "untrust",
  "panel",
  "info",
] as const;
export type TempVoiceAction = (typeof TEMPVOICE_ACTIONS)[number];

// ─── Panel de control configurable ──────────────────────────────────────────────
// Debe coincidir con `DBTempVoicePanel*` de library-shared y el catálogo del módulo.

/** El panel es SOLO botones. Acciones directas (se ejecutan al pulsar). */
export const PANEL_DIRECT_ACTIONS = ["lock", "unlock", "claim", "info"] as const;
/** Acciones que abren un desplegable en un efímero al pulsar el botón. */
export const PANEL_STRING_SELECT_ACTIONS = ["limit", "bitrate", "region"] as const;
export const PANEL_USER_SELECT_ACTIONS = [
  "permit",
  "kick",
  "reject",
  "transfer",
  "trust",
] as const;
export const PANEL_SELECT_ACTIONS = [
  ...PANEL_STRING_SELECT_ACTIONS,
  ...PANEL_USER_SELECT_ACTIONS,
] as const;
/** Acciones que abren un MODAL (texto libre) al pulsar el botón, en vez de un
 *  desplegable: `name` pide el nombre nuevo del canal. */
export const PANEL_MODAL_ACTIONS = ["name"] as const;
/** Todas las acciones asignables a un botón, en orden de UI (directas primero). */
export const PANEL_ACTIONS = [
  ...PANEL_DIRECT_ACTIONS,
  ...PANEL_SELECT_ACTIONS,
  ...PANEL_MODAL_ACTIONS,
] as const;
export const PANEL_BUTTON_STYLES = [
  "primary",
  "secondary",
  "success",
  "danger",
] as const;

export type TempVoicePanelDirectAction = (typeof PANEL_DIRECT_ACTIONS)[number];
export type TempVoicePanelSelectAction = (typeof PANEL_SELECT_ACTIONS)[number];
export type TempVoicePanelModalAction = (typeof PANEL_MODAL_ACTIONS)[number];
export type TempVoicePanelAction = (typeof PANEL_ACTIONS)[number];
export type TempVoicePanelButtonStyle = (typeof PANEL_BUTTON_STYLES)[number];

export interface DBTempVoicePanelButton {
  action: TempVoicePanelAction;
  label: string;
  /** Emoji unicode (`🔒`) o custom (`<:nombre:id>`). `null` = sin emoji. */
  emoji: string | null;
  style: TempVoicePanelButtonStyle;
}
export interface DBTempVoicePanel {
  /** Admite variables `{owner}`, `{channel}`, `{count}`. */
  title: string;
  description: string;
  buttons: DBTempVoicePanelButton[];
}

/** ¿La acción abre un desplegable efímero al pulsar el botón (vs ejecutarse directa)? */
export function isPanelSelectAction(
  action: TempVoicePanelAction,
): action is TempVoicePanelSelectAction {
  return (PANEL_SELECT_ACTIONS as readonly string[]).includes(action);
}

/** ¿La acción abre un modal (texto libre) al pulsar el botón? */
export function isPanelModalAction(
  action: TempVoicePanelAction,
): action is TempVoicePanelModalAction {
  return (PANEL_MODAL_ACTIONS as readonly string[]).includes(action);
}

export interface DBModuleTempVoice {
  schema_version: number;
  enabled: boolean;
  /** Acceso global; cada comando lo hereda por eje según su `use_global`. */
  commands_global: DBCommandAccess;
  /** Config por comando, keyed por nombre (ver TEMPVOICE_COMMANDS). */
  commands: Record<string, DBConfigurableCommand>;
  creators: DBTempVoiceCreator[];
  /** Palabras prohibidas en los nombres de los canales temporales. Vacío = sin filtro. */
  name_blacklist: string[];
  /** Panel de control configurable (textos + botones). */
  panel: DBTempVoicePanel;
  /** Modo de invocación de los comandos `/voice`: solo barra, solo prefijo, o ambos. */
  command_mode: TempVoiceCommandMode;
  defaults: DBTempVoiceDefaults;
}

export const TEMPVOICE_COMMAND_MODES = ["slash", "prefix", "both"] as const;
export type TempVoiceCommandMode = (typeof TEMPVOICE_COMMAND_MODES)[number];

// Inlined helper — equivalente a `createZodObject` de
// `library-shared/src/db/utils.ts`. El dist CJS publicado no lo expone como
// named export resoluble por el bundle de browser de Vite.
type TypeToZod<T> = {
  [K in keyof T]: z.ZodType<T[K]> | z.ZodType<Exclude<T[K], undefined>>;
};
function createZodObject<T, S extends TypeToZod<T> = TypeToZod<T>>(obj: S) {
  return z.object(
    obj as Record<string, z.ZodType>,
  ) as unknown as z.ZodObject<S>;
}

// Rango de bitrate: Discord acepta 8k–96k sin boosts; hasta 384k con boosts.
export const MIN_BITRATE = 8000;
export const MAX_BITRATE = 384000;
export const MIN_USER_LIMIT = 0;
export const MAX_USER_LIMIT = 99;

/**
 * Máximo de creadores OPERATIVOS sin Kena Premium (server). Los que excedan el
 * tope se conservan guardados pero el bot los ignora (y aquí solo se pueden
 * eliminar). ⚠️ Debe coincidir con `FREE_CREATOR_LIMIT` del módulo
 * (`modules/tempvoice-module/src/shared/premium.ts`).
 */
export const FREE_CREATOR_LIMIT = 2;

/** Largo máximo del nombre del creador (sólo etiqueta del dashboard). */
export const MAX_CREATOR_NAME = 60;

/** Plantilla de nombre de fábrica. La usan tanto `defaults.name_template` como
 *  el creador nuevo, y es lo que repone el botón "Por defecto" del editor. */
export const TEMPVOICE_DEFAULT_NAME_TEMPLATE = "{user}";

/**
 * Texto obligatorio: ni vacío ni solo espacios.
 *
 * En el dashboard un campo de texto vacío YA NO significa "usa el valor por
 * defecto" — dejarlo en blanco bloquea el guardado y se lista en el aviso rojo
 * del formulario. Para volver al valor de fábrica está el botón "Por defecto"
 * junto al campo, que lo rellena con el texto literal.
 */
const nonBlankText = (max: number) =>
  z
    .string()
    .max(max)
    .refine((v) => v.trim().length > 0, {
      message: "No puede estar vacío",
    });

// ⚠️ El panel se declara ANTES que el creador porque `panel_override` lo
// referencia: son `const`, no hay hoisting — moverlos abajo rompe el módulo en
// tiempo de carga (`Cannot access 'tempvoicePanelSchema' before initialization`).
export const panelButtonSchema = createZodObject<DBTempVoicePanelButton>({
  action: z.enum(PANEL_ACTIONS),
  // Obligatorio: Discord rechaza un botón sin etiqueta (COMPONENT_*) y el panel
  // no se llegaría a publicar. El botón "Por defecto" repone la de la acción.
  label: nonBlankText(80),
  emoji: z.string().nullable(),
  style: z.enum(PANEL_BUTTON_STYLES),
});
export const tempvoicePanelSchema = createZodObject<DBTempVoicePanel>({
  title: z.string().max(256),
  // "" = usa el default localizado (el bot lo resuelve). Pero un texto SOLO con
  // espacios/saltos es el campo vaciado a mano y NO puede guardarse: el bot
  // publicaría un panel sin texto.
  description: z
    .string()
    .max(2000)
    .refine((v) => v === "" || v.trim().length > 0, {
      message: "No puede estar vacío",
    }),
  buttons: z.array(panelButtonSchema),
});

export const tempvoiceCreatorSchema = createZodObject<DBTempVoiceCreator>({
  // Obligatorio: es la etiqueta con la que se identifica la fila plegada.
  name: nonBlankText(MAX_CREATOR_NAME),
  // Requerido: el creador no vale sin canal. Bloquea el save hasta elegirlo.
  channel_id: z.string().min(1),
  parent_id: z.string().nullable(),
  // Obligatorio: el backend sigue aceptando "" (cae a `defaults.name_template`),
  // pero el dashboard ya no deja guardarlo vacío — se repone con el botón.
  name_template: nonBlankText(100),
  user_limit: z.number().int().min(MIN_USER_LIMIT).max(MAX_USER_LIMIT),
  bitrate: z.number().int().min(MIN_BITRATE).max(MAX_BITRATE),
  locked: z.boolean(),
  panel_channel_id: z.string().nullable(),
  panel_enabled: z.boolean(),
  text_chat_enabled: z.boolean(),
  rtc_region: z.string().nullable(),
  moderator_role_ids: z.array(z.string()),
  // Lista de DENEGADAS: vacío = todas permitidas (comportamiento previo al campo).
  denied_actions: z.array(z.enum(TEMPVOICE_ACTIONS)),
  // `null` = usa el panel global del módulo.
  panel_override: tempvoicePanelSchema.nullable(),
});

export const tempvoiceDefaultsSchema = createZodObject<DBTempVoiceDefaults>({
  user_limit: z.number().int().min(MIN_USER_LIMIT).max(MAX_USER_LIMIT),
  bitrate: z.number().int().min(MIN_BITRATE).max(MAX_BITRATE),
  locked: z.boolean(),
  name_template: z.string().max(100),
});

export const accessListSchema = createZodObject<DBAccessList>({
  mode: z.enum(["only", "all_except"]),
  ids: z.array(z.string()),
});

export const commandAccessSchema = createZodObject<DBCommandAccess>({
  roles: accessListSchema,
  channels: accessListSchema,
  categories: accessListSchema,
});

export const commandSyncSchema = createZodObject<DBTempVoiceCommandSync>({
  roles: z.boolean(),
  channels: z.boolean(),
  categories: z.boolean(),
});

export const configurableCommandSchema =
  createZodObject<DBConfigurableCommand>({
    enabled: z.boolean(),
    use_global: commandSyncSchema,
    access: commandAccessSchema,
  });

// Palabras prohibidas: se recortan a 100 chars (límite de nombre de canal) y no
// pueden ser vacías. El máximo de entradas lo aplica la UI (MAX_BLACKLIST_WORDS).
export const nameBlacklistSchema = z.array(z.string().trim().min(1).max(100));

export const moduleTempvoiceSchema = createZodObject<DBModuleTempVoice>({
  schema_version: z.number(),
  enabled: z.boolean(),
  commands_global: commandAccessSchema,
  commands: z.record(z.string(), configurableCommandSchema),
  creators: z.array(tempvoiceCreatorSchema),
  name_blacklist: nameBlacklistSchema,
  panel: tempvoicePanelSchema,
  command_mode: z.enum(TEMPVOICE_COMMAND_MODES),
  defaults: tempvoiceDefaultsSchema,
});

export type ModuleTempVoiceSchema = DBModuleTempVoice;

// El backend PATCHea vía `$set` con claves top-level opcionales.
// `schema_version` se acepta pero nunca se edita desde el dashboard.
//
// Activar el módulo SIN ningún creador está permitido: el backend lo trata como
// un no-op seguro (no se crea ningún canal temporal hasta que hay un creador),
// así que el admin puede encender el módulo y añadir creadores después. Lo que
// sí bloquea el guardado es un creador incompleto: `tempvoiceCreatorSchema`
// exige `channel_id` (`.min(1)`), y el `TempVoiceForm` resume qué falta.
export const sendTempvoiceChangesSchema = moduleTempvoiceSchema
  .omit({ schema_version: true })
  .partial();
export type SendTempvoiceChangesSchema = z.infer<
  typeof sendTempvoiceChangesSchema
>;

/**
 * Centinela de canal: representa "el canal temporal creado" en las listas de acceso
 * de canales. NO es un ID real de Discord — los canales temporales tienen un ID
 * distinto cada vez, así que se referencian con este marcador y el backend lo resuelve
 * en runtime (¿el canal de invocación es un canal temporal registrado?).
 *
 * ⚠️ Debe coincidir con `TEMP_CHANNEL_SENTINEL` del backend
 * (`modules/tempvoice-module/src/commands/voice/voice.ts`).
 */
export const TEMP_CHANNEL_SENTINEL = "temp_created";

/**
 * Pseudo-roles (no son IDs de rol reales) que el backend resuelve en runtime dentro
 * de la lista de ROLES:
 *  - `temp_owner`   → el dueño del canal temporal.
 *  - `temp_managers`→ los gestores que el dueño ha delegado.
 * Permiten el default "solo dueño y sus gestores" y que el admin amplíe con roles
 * reales (p. ej. @Moderador) o lo abra a todos.
 *
 * ⚠️ Deben coincidir con los del backend
 * (`modules/tempvoice-module/src/commands/voice/voice.ts`).
 */
export const TEMP_OWNER_SENTINEL = "temp_owner";
export const TEMP_MANAGERS_SENTINEL = "temp_managers";

// Acceso por defecto: blacklist vacía = sin restricción (todos pueden).
export const defaultAccessList = (): DBAccessList => ({
  mode: "all_except",
  ids: [],
});

// Roles por defecto: whitelist con SOLO el dueño y sus gestores, para que de fábrica
// los comandos /voice los use únicamente quien es dueño del canal (o a quien delegue).
// El admin puede añadir roles reales o abrirlo a todos desde el dashboard.
export const defaultRoleAccess = (): DBAccessList => ({
  mode: "only",
  ids: [TEMP_OWNER_SENTINEL, TEMP_MANAGERS_SENTINEL],
});

// Canales por defecto: whitelist con SOLO el canal temporal creado, para que de
// fábrica los comandos /voice funcionen únicamente dentro del chat del canal temporal
// (plug & play, sin tener que enumerar IDs que además son dinámicos).
export const defaultChannelAccess = (): DBAccessList => ({
  mode: "only",
  ids: [TEMP_CHANNEL_SENTINEL],
});

export const defaultCommandAccess = (): DBCommandAccess => ({
  roles: defaultRoleAccess(),
  channels: defaultChannelAccess(),
  categories: defaultAccessList(),
});

// Sincronización por defecto: los tres ejes heredan el acceso global.
export const defaultCommandSync = (): DBTempVoiceCommandSync => ({
  roles: true,
  channels: true,
  categories: true,
});

// Comando por defecto: habilitado y con los tres ejes heredando el acceso global.
export const defaultConfigurableCommand = (): DBConfigurableCommand => ({
  enabled: true,
  use_global: defaultCommandSync(),
  access: defaultCommandAccess(),
});

// Cada comando arranca habilitado y heredando el acceso global.
export function createDefaultCommands(): Record<string, DBConfigurableCommand> {
  return Object.fromEntries(
    TEMPVOICE_COMMANDS.map((cmd) => [cmd, defaultConfigurableCommand()]),
  );
}

// Metadatos de presentación de cada acción (label + emoji + estilo sugeridos) para
// el editor del panel. Espeja los defaults del backend (DEFAULT_TEMPVOICE_PANEL).
//
// `label` es el seed ESPAÑOL, el mismo que el backend siembra al crear el módulo:
// no es lo que se enseña, es el marcador de "este guild no ha personalizado el
// botón". Lo que se pinta (aquí y en el panel que publica el bot) es `labelKey`
// resuelta al idioma del guild — ver `resolvePanelButtonLabel`.
export const PANEL_ACTION_META: Record<
  TempVoicePanelAction,
  {
    label: string;
    /** Clave i18n (contexto `tempvoice`) de la etiqueta por defecto del botón.
     *  Espeja `BUTTON_LABEL_KEY` del módulo (`shared/panelActions.ts`). */
    labelKey: string;
    emoji: string;
    style: TempVoicePanelButtonStyle;
    placeholder: string;
  }
> = {
  lock: { label: "Bloquear", labelKey: "panelButtonLock", emoji: "<:tv_lock:1528116157268103228>", style: "secondary", placeholder: "Bloquear el canal" },
  unlock: { label: "Desbloquear", labelKey: "panelButtonUnlock", emoji: "<:tv_unlock:1528116290504491059>", style: "secondary", placeholder: "Desbloquear el canal" },
  claim: { label: "Reclamar", labelKey: "panelButtonClaim", emoji: "<:tv_claim:1528116067279306812>", style: "primary", placeholder: "Reclamar la propiedad" },
  info: { label: "Info", labelKey: "panelButtonInfo", emoji: "<:tv_info:1528116087231611062>", style: "secondary", placeholder: "Ver info del canal" },
  limit: { label: "Límite", labelKey: "panelButtonLimit", emoji: "<:tv_limit:1528116133897703517>", style: "secondary", placeholder: "Cambiar límite de usuarios" },
  bitrate: { label: "Bitrate", labelKey: "panelButtonBitrate", emoji: "<:tv_bitrate:1528116045007683706>", style: "secondary", placeholder: "Cambiar bitrate" },
  region: { label: "Región", labelKey: "panelButtonRegion", emoji: "<:tv_region:1528116209596235806>", style: "secondary", placeholder: "Cambiar región de voz" },
  permit: { label: "Permitir", labelKey: "panelButtonPermit", emoji: "<:tv_permit:1528116185961332767>", style: "success", placeholder: "Permitir a un usuario" },
  kick: { label: "Expulsar", labelKey: "panelButtonKick", emoji: "<:tv_kick:1528116112267411537>", style: "danger", placeholder: "Expulsar a un usuario" },
  reject: { label: "Vetar", labelKey: "panelButtonReject", emoji: "<:tv_reject:1528116232639742102>", style: "danger", placeholder: "Vetar a un usuario" },
  transfer: { label: "Transferir", labelKey: "panelButtonTransfer", emoji: "<:tv_transfer:1528116252005105745>", style: "primary", placeholder: "Transferir la propiedad" },
  trust: { label: "Gestores", labelKey: "panelButtonTrust", emoji: "<:tv_trust:1528116271722270760>", style: "success", placeholder: "Dar permisos de gestión del canal" },
  // Abre un MODAL para teclear el nombre nuevo (no un desplegable).
  name: { label: "Renombrar", labelKey: "panelButtonName", emoji: "<:tv_name:1529442111487742114>", style: "secondary", placeholder: "Cambiar el nombre del canal" },
};

export function createPanelButton(
  action: TempVoicePanelAction,
): DBTempVoicePanelButton {
  const meta = PANEL_ACTION_META[action];
  return { action, label: meta.label, emoji: meta.emoji, style: meta.style };
}

// Panel por defecto (SOLO botones): espeja DEFAULT_TEMPVOICE_PANEL del backend.
export function createDefaultPanel(): DBTempVoicePanel {
  return {
    // `title` inerte: el panel es UN SOLO recuadro (ver DEFAULT_TEMPVOICE_PANEL del
    // backend). Se conserva por el schema, pero el default va vacío.
    title: "",
    description:
      "Usa los botones de abajo para gestionar tu canal, o los comandos `/voice`.\nSolo el dueño del canal puede usar estos controles.",
    buttons: [
      createPanelButton("lock"),
      createPanelButton("unlock"),
      createPanelButton("claim"),
      createPanelButton("info"),
      createPanelButton("limit"),
      createPanelButton("bitrate"),
      createPanelButton("region"),
      createPanelButton("permit"),
      createPanelButton("kick"),
    ],
  };
}

// Mirror de `moduleTempVoiceMock` del backend (api-db guild-mock.ts).
export const defaultTempvoiceValues: ModuleTempVoiceSchema = {
  // v10 = `denied_actions` + `panel_override` por creador (ver library-shared).
  schema_version: 10,
  enabled: false,
  commands_global: defaultCommandAccess(),
  commands: createDefaultCommands(),
  creators: [],
  name_blacklist: [],
  panel: createDefaultPanel(),
  command_mode: "both",
  defaults: {
    user_limit: 0,
    bitrate: 64000,
    locked: false,
    name_template: TEMPVOICE_DEFAULT_NAME_TEMPLATE,
  },
};

export function createCreator(): DBTempVoiceCreator {
  return {
    // Vacío a propósito: el admin DEBE nombrarlo (bloquea el guardado hasta
    // entonces, igual que el canal de voz).
    name: "",
    channel_id: "",
    parent_id: null,
    // Nace con la plantilla de fábrica escrita literal, no vacía: un campo en
    // blanco es un error de validación, no un "usa el valor por defecto".
    name_template: TEMPVOICE_DEFAULT_NAME_TEMPLATE,
    user_limit: 0,
    bitrate: 64000,
    locked: false,
    panel_channel_id: null,
    panel_enabled: true,
    text_chat_enabled: true,
    rtc_region: null,
    moderator_role_ids: [],
    // Nada denegado y panel global: el creador nuevo se comporta como antes de
    // que existieran los dos campos.
    denied_actions: [],
    panel_override: null,
  };
}

package validations

import (
	"kena.bot/api-db-go/internal/domain/dbguild"
)

// UpdateModuleTempvoiceBody mirrors the Node `updateModuleTempVoiceSchema` (a
// `.strict()` object of `.optional()` fields). Unlike the READ schema, the
// PATCH schema excludes only `schema_version` and `updated_at` (server-managed).
// The top-level `name_blacklist`, `panel` and `command_mode` (added in v3/v4/v7)
// ARE patchable — omitting them here made the strict decoder reject them as
// `unrecognized_keys` on any PATCH that included them (e.g. saving the panel from
// the dashboard) → 400. Every field is a pointer so the strict decoder can validate
// the shape; the handler then re-decodes the SAME raw body as `map[string]any`,
// which the repository merges into the existing subdoc via
// `mongo.MergeDeepJSON` by KEY PRESENCE: a key absent in the body is left
// alone; an explicit `false`/`0`/`""`/`null` is applied and overrides the
// stored value; nested objects recurse (so a partial
// `{"defaults":{"bitrate":96000}}` PATCH preserves the other defaults);
// slices (`creators`) replace wholesale; maps merge per-key.
//
// PER OLA-3 NOTE: the greeter/logs/music bodies bind via Fiber's default
// decoder (silently drops unknown keys, parity with Mongoose) — only
// modmail/tempvoice/giveaway/moderation carry the strict unknown-key
// rejection. The nested field types are the full `dbguild.Tempvoice*`
// shapes: every zod PATCH sub-schema matches its parent type
// field-for-field, so no valid key is rejected. Go's json decoder does
// NOT enforce zod's REQUIRED-ness inside a present nested object, so a
// partial command entry that Node would 400 is accepted here and the
// missing leaves stay zero — the same non-strict-required behaviour
// every Go module body has.
type UpdateModuleTempvoiceBody struct {
	Enabled        *bool                                `json:"enabled,omitempty"`
	Creators       *[]dbguild.TempvoiceCreator          `json:"creators,omitempty"`
	NameBlacklist  *[]string                            `json:"name_blacklist,omitempty"`
	Panel          *dbguild.TempvoicePanel              `json:"panel,omitempty"`
	CommandMode    *dbguild.TempvoiceCommandMode        `json:"command_mode,omitempty"`
	Defaults       *dbguild.TempvoiceDefaults           `json:"defaults,omitempty"`
	CommandsGlobal *dbguild.TempvoiceCommandAccess      `json:"commands_global,omitempty"`
	Commands       *map[string]dbguild.TempvoiceCommand `json:"commands,omitempty"`
}

