package validations

import (
	"strconv"

	"kena.bot/api-db-go/internal/domain/dbguild"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
)

// UpdateModuleGreeterBody mirrors the Node `updateModuleGreeterSchema`
// (which is `greeterSchema.partial()`). All fields are pointers so the
// strict decoder can validate the shape (enums / nested structs) before
// the handler re-decodes the raw body as `map[string]any` and forwards
// it to the repository, which `mongo.MergeDeepJSON`-merges it into the
// existing subdoc by KEY PRESENCE (a key absent in the body is left
// alone; an explicit `false`/`0`/`""`/`null` is applied and overrides
// the stored value; nested objects recurse; slices replace wholesale;
// maps merge per-key).
//
// PER OLA-3 NOTE: this body is NOT strict. The handler binds with Fiber's
// default decoder (`c.Bind().Body`), which silently drops unknown keys —
// parity with Mongoose, same as logs/music. Only modmail/tempvoice/giveaway/
// moderation call `DisallowUnknownFields`; see the matching note in
// `module_tempvoice_validations.go`.
//
// Consequence to keep in mind: a client typo returns 200 as if it had been
// applied. It does not corrupt data — `MergeDeepJSON` drops any key that
// matches no json tag — and the server-owned fields (`schema_version`,
// `updated_at`, `enabled_since`) are re-stamped by the repository even if a
// client sends them, which is what keeps the write-once `enabled_since`
// invariant safe. See `module_greeter_repository.go`.
type UpdateModuleGreeterBody struct {
	Enabled *bool                         `json:"enabled,omitempty"`
	Welcome *dbguild.GreeterMessageConfig `json:"welcome,omitempty"`
	Goodbye *dbguild.GreeterMessageConfig `json:"goodbye,omitempty"`
	Boost   *dbguild.GreeterMessageConfig `json:"boost,omitempty"`
	// Hermano de `boost` en la forma, pero depende de él en comportamiento:
	// la reacción marca el mensaje que `boost` publica (ver
	// `DBGreeterBoostReaction` en library-shared). Va fuera porque `boost`
	// comparte forma con welcome/goodbye, donde no significaría nada.
	BoostReaction *dbguild.GreeterBoostReaction `json:"boost_reaction,omitempty"`
	JoinRoles     *dbguild.JoinRoles            `json:"join_roles,omitempty"`
	Captcha       *dbguild.GreeterCaptcha       `json:"captcha,omitempty"`
	Variables     *dbguild.GreeterVariables     `json:"variables,omitempty"`
}

// Límites duros de la API de Discord. No son gusto nuestro: pasarse de aquí
// hace que Discord rechace el mensaje con 400 y la bienvenida NUNCA salga -en
// silencio, porque el error sólo aparece en los logs del bot-. Antes no había
// tope en ninguna capa: ni aquí, ni en el zod del dashboard. 32 KB de
// `message.content` se persistían tan contentos y el guild se quedaba sin
// bienvenidas para siempre.
const (
	maxGreeterContent     = 2000
	maxGreeterEmbedTitle  = 256
	maxGreeterEmbedDesc   = 4096
	maxGreeterEmbedFooter = 2048
	maxGreeterURL         = 2048
	maxGreeterButtonLabel = 80

	// Discord no deja más de 250 roles por servidor, así que una lista más
	// larga sólo puede ser basura o un intento de ahogar al bot: asigna con un
	// `for` secuencial y DOS llamadas a la API por rol.
	maxJoinRoles = 250

	// Cada capa de tipo `image`/`avatar` es una descarga remota más, en serie,
	// por cada miembro que entra.
	maxCanvasElements = 100

	// 4096x4096 en RGBA son 64 MB de heap NATIVO, que `--max-old-space-size`
	// no acota. Sin techo, `width: 50000` pedía ~10 GB y se llevaba por delante
	// el proceso que sirve a TODOS los guilds.
	maxCanvasSide = 4096

	// 14 días. Por encima de 2^31-1 milisegundos (~24,8 días) `setTimeout` de
	// Node desborda, avisa con `TimeoutOverflowWarning` y coacciona el retardo
	// a 1 ms: el mensaje que debía borrarse dentro de un mes se borraba al
	// instante. Invertía la intención del usuario sin decir nada.
	maxDelaySeconds = 14 * 24 * 60 * 60
)

func maxLen(value *string, limit int, property string) *apierrors.CustomError {
	if value == nil || len([]rune(*value)) <= limit {
		return nil
	}
	return zodItemError(
		"Too big: expected string to have <="+strconv.Itoa(limit)+" characters",
		property,
	)
}

func inRange(value *int, limit int, property string) *apierrors.CustomError {
	if value == nil {
		return nil
	}
	if *value < 0 {
		return zodItemError("Too small: expected number to be >=0", property)
	}
	if *value > limit {
		return zodItemError(
			"Too big: expected number to be <="+strconv.Itoa(limit),
			property,
		)
	}
	return nil
}

func validateGreeterEmbed(e *dbguild.GreeterEmbed, prefix string) *apierrors.CustomError {
	if e == nil {
		return nil
	}
	for _, c := range []struct {
		value    *string
		limit    int
		property string
	}{
		{e.Title, maxGreeterEmbedTitle, prefix + "title"},
		{e.Description, maxGreeterEmbedDesc, prefix + "description"},
		{e.Footer, maxGreeterEmbedFooter, prefix + "footer"},
		{e.ImageURL, maxGreeterURL, prefix + "image_url"},
		{e.ThumbnailURL, maxGreeterURL, prefix + "thumbnail_url"},
	} {
		if err := maxLen(c.value, c.limit, c.property); err != nil {
			return err
		}
	}
	return nil
}

// validateGreeterImage aplica los topes del bloque `image` (tamaño de
// canvas, nº de elementos, longitud de URLs). Canal y privado comparten esta
// función -mismo tipo `dbguild.GreeterImage`, mismos límites- porque un
// canvas de privado puede llegar por PATCH directo igual que el de canal:
// nada en el transporte HTTP distingue a uno del otro, así que ambos
// necesitan el mismo candado. `prefix` ya incluye el segmento propio con el
// punto final (p.ej. "welcome.image." o "welcome.dm.image."), igual que hace
// validateGreeterEmbed con el suyo.
func validateGreeterImage(img *dbguild.GreeterImage, prefix string) *apierrors.CustomError {
	if err := maxLen(img.BackgroundURL, maxGreeterURL, prefix+"background_url"); err != nil {
		return err
	}

	canvas := &img.Canvas
	if canvas.Width > maxCanvasSide || canvas.Height > maxCanvasSide {
		return zodItemError(
			"Too big: expected number to be <="+strconv.Itoa(maxCanvasSide),
			prefix+"canvas",
		)
	}
	if canvas.Width < 0 || canvas.Height < 0 {
		return zodItemError("Too small: expected number to be >=0", prefix+"canvas")
	}
	if len(canvas.Elements) > maxCanvasElements {
		return zodItemError(
			"Too big: expected array to have <="+strconv.Itoa(maxCanvasElements)+" items",
			prefix+"canvas.elements",
		)
	}
	if err := maxLen(
		canvas.BackgroundURL,
		maxGreeterURL,
		prefix+"canvas.background_url",
	); err != nil {
		return err
	}
	for i := range canvas.Elements {
		if err := maxLen(
			canvas.Elements[i].URL,
			maxGreeterURL,
			prefix+"canvas.elements."+strconv.Itoa(i)+".url",
		); err != nil {
			return err
		}
	}
	return nil
}

func validateGreeterMessageConfig(
	c *dbguild.GreeterMessageConfig,
	prefix string,
) *apierrors.CustomError {
	if c == nil {
		return nil
	}

	if err := maxLen(&c.Message.Content, maxGreeterContent, prefix+"message.content"); err != nil {
		return err
	}
	if err := validateGreeterEmbed(&c.Embed, prefix+"embed."); err != nil {
		return err
	}
	if err := maxLen(&c.DM.Message.Content, maxGreeterContent, prefix+"dm.message.content"); err != nil {
		return err
	}
	if err := validateGreeterEmbed(&c.DM.Embed, prefix+"dm.embed."); err != nil {
		return err
	}
	if err := inRange(
		c.Behavior.DeleteAfterSeconds,
		maxDelaySeconds,
		prefix+"behavior.delete_after_seconds",
	); err != nil {
		return err
	}
	if err := inRange(
		c.DM.DeleteAfterSeconds,
		maxDelaySeconds,
		prefix+"dm.delete_after_seconds",
	); err != nil {
		return err
	}
	// El canvas de privado puede llegar por PATCH directo igual que el de
	// canal -nada en el transporte los distingue-, así que se valida con los
	// mismos topes. Ver validateGreeterImage.
	if err := validateGreeterImage(&c.Image, prefix+"image."); err != nil {
		return err
	}
	if err := validateGreeterImage(&c.DM.Image, prefix+"dm.image."); err != nil {
		return err
	}
	return nil
}

// ValidateUpdateModuleGreeter aplica los topes que faltaban por completo en el
// servidor. El zod del dashboard sí revalida en su propio servidor, pero eso
// sólo cubre a quien entra POR el dashboard: este endpoint acepta un PATCH
// directo con la credencial de api-db y no tenía nada que lo parase.
//
// Sólo mira lo que el cuerpo trae: `UpdateModuleGreeterBody` es un parcial y
// un puntero nil significa «no tocar este bloque», no «vacío».
func ValidateUpdateModuleGreeter(body *UpdateModuleGreeterBody) *apierrors.CustomError {
	for _, b := range []struct {
		config *dbguild.GreeterMessageConfig
		prefix string
	}{
		{body.Welcome, "welcome."},
		{body.Goodbye, "goodbye."},
		{body.Boost, "boost."},
	} {
		if err := validateGreeterMessageConfig(b.config, b.prefix); err != nil {
			return err
		}
	}

	if body.JoinRoles != nil {
		if len(body.JoinRoles.RolesID) > maxJoinRoles {
			return zodItemError(
				"Too big: expected array to have <="+strconv.Itoa(maxJoinRoles)+" items",
				"join_roles.roles_id",
			)
		}
		if err := inRange(
			body.JoinRoles.DelaySeconds,
			maxDelaySeconds,
			"join_roles.delay_seconds",
		); err != nil {
			return err
		}
	}

	if body.Captcha != nil {
		if err := maxLen(
			&body.Captcha.ButtonLabel,
			maxGreeterButtonLabel,
			"captcha.button_label",
		); err != nil {
			return err
		}
		if e := body.Captcha.WelcomeEmbed; e != nil {
			if err := maxLen(&e.Title, maxGreeterEmbedTitle, "captcha.welcome_embed.title"); err != nil {
				return err
			}
			if err := maxLen(
				&e.Description,
				maxGreeterEmbedDesc,
				"captcha.welcome_embed.description",
			); err != nil {
				return err
			}
			if err := maxLen(e.Footer, maxGreeterEmbedFooter, "captcha.welcome_embed.footer"); err != nil {
				return err
			}
		}
	}

	return nil
}

package validations

import (
	"fmt"

	"kena.bot/api-db-go/internal/domain/dbguild"
	"kena.bot/api-db-go/internal/domain/dbmodmailticket"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
)

// UpdateModuleModmailBody mirrors the Node `updateModuleModmailSchema` (a
// `.strict()` object of `.optional()` fields). Every field is a pointer so
// the strict decoder can validate the shape — and the top-level + nested
// nullables ride through the merge without losing PRESENCE. The handler
// decodes this with `DisallowUnknownFields` (matching the zod `.strict()`
// — unknown keys top-level OR nested are a 400) and then re-decodes the
// SAME raw body as `map[string]any`, which the repository merges into the
// existing subdoc via `mongo.MergeDeepJSON` by KEY PRESENCE: a key absent
// in the body is left alone; an explicit `false`/`0`/`""`/`null` is
// applied and overrides the stored value (so `null` sent on a top-level
// nullable like `log_channel_id` clears it); nested objects recurse;
// slices replace wholesale; maps merge per-key.
//
// PER OLA-3 NOTE: the greeter/logs/music bodies bind via Fiber's default
// decoder (silently drops unknown keys, parity with Mongoose) — only
// modmail/tempvoice/giveaway/moderation carry the strict unknown-key
// rejection. The nested field types are the full `dbguild.Modmail*`
// shapes: every zod PATCH sub-schema matches its parent type
// field-for-field, so no valid key is rejected. Go's json decoder does
// NOT enforce zod's REQUIRED-ness inside a present nested object, so a
// partial sub-object that Node would 400 is accepted here and the missing
// leaves stay zero — the same non-strict-required behaviour every Go
// module body has.
type UpdateModuleModmailBody struct {
	SchemaVersion *int                       `json:"schema_version,omitempty"`
	Enabled       *bool                      `json:"enabled,omitempty"`
	GuildID       *string                    `json:"guild_id,omitempty"`
	BaseTicket    *dbguild.ModmailBaseTicket `json:"base_ticket,omitempty"`
	LogChannelID  *string                    `json:"log_channel_id,omitempty"`
	// LogAutoPublish llegó con el v8 del subdoc pero se quedó fuera de este
	// struct: con `DisallowUnknownFields`, el PATCH del dashboard que tocara el
	// interruptor de crosspost moría con un 400 por clave desconocida.
	LogAutoPublish *bool                  `json:"log_auto_publish,omitempty"`
	MainGuildID    *string                `json:"main_guild_id,omitempty"`
	SpecialGuildID *string                `json:"special_guild_id,omitempty"`
	Colors         *dbguild.ModmailColors `json:"colors,omitempty"`
	MessageColors  *map[string]*string    `json:"message_colors,omitempty"`
	MessageImages  *map[string]*string    `json:"message_images,omitempty"`
	// Gemelos de MessageImages. Sin ellos aquí el PATCH del dashboard moriría
	// con un 400 por clave desconocida (`DisallowUnknownFields`), igual que le
	// pasó a LogAutoPublish.
	MessageFooters             *map[string]*string                      `json:"message_footers,omitempty"`
	MessageFooterIcons         *map[string]*string                      `json:"message_footer_icons,omitempty"`
	Messages                   *map[string]string                       `json:"messages,omitempty"`
	// CommandMode: sin este campo aquí, el PATCH del dashboard que tocara el
	// modo de invocación de los comandos de staff moriría con un 400 por clave
	// desconocida (`DisallowUnknownFields`), igual que le pasó a LogAutoPublish.
	CommandMode                *string                                  `json:"command_mode,omitempty"`
	CommandTriggers            *dbguild.ModmailCommandTriggers          `json:"command_triggers,omitempty"`
	CustomCommands             *dbguild.ModmailCommandsBlock            `json:"custom_commands,omitempty"`
	Aliases                    *dbguild.ModmailCommandsBlock            `json:"aliases,omitempty"`
	TicketTypes                *[]dbguild.ModmailTicketType             `json:"ticket_types,omitempty"`
	DirectOpen                 *dbguild.ModmailDirectOpen               `json:"direct_open,omitempty"`
	SpecialTypesInMain         *bool                                    `json:"special_types_in_main,omitempty"`
	TicketTypeEmojis           *bool                                    `json:"ticket_type_emojis,omitempty"`
	AnonymousIcon              *bool                                    `json:"anonymous_icon,omitempty"`
	IdentifiedIcon             *bool                                    `json:"identified_icon,omitempty"`
	DmAckReaction              *dbguild.ModmailDmAckReaction            `json:"dm_ack_reaction,omitempty"`
	StaffMessageActionEmojis   *dbguild.ModmailStaffActionEmojis        `json:"staff_message_action_emojis,omitempty"`
	StaffCommands              *map[string]dbguild.ModmailCommandAccess `json:"staff_commands,omitempty"`
	ContactCategoryID          *string                                  `json:"contact_category_id,omitempty"`
	ContactChannelNameTemplate *string                                  `json:"contact_channel_name_template,omitempty"`
	WebAccess                  *dbguild.ModmailWebAccess                `json:"web_access,omitempty"`
	// Blacklist (v10): entradas de veto (usuario + motivo/quién/cuándo). Slice
	// → el merge la reemplaza ENTERA, que es justo lo que el dashboard manda
	// (la lista completa tras añadir/quitar).
	Blacklist *[]dbguild.ModmailBlacklistEntry `json:"blacklist,omitempty"`
	// Cooldown entre tickets (v10): minutos de espera tras un cierre. Nullable:
	// un `null` explícito lo APAGA (el merge por presencia lo aplica).
	TicketCooldownMinutes *int `json:"ticket_cooldown_minutes,omitempty"`
	// Modo mantenimiento (v10).
	SupportClosed *dbguild.ModmailSupportClosed `json:"support_closed,omitempty"`
	// Typing indicators (v10).
	TypingForward   *dbguild.ModmailTypingForward `json:"typing_forward,omitempty"`
	SupportSchedule *dbguild.SupportSchedule      `json:"support_schedule,omitempty"`
}

// ValidateModmailTicketTypes valida la lista `ticket_types` de un PATCH: ningún
// tipo REAL puede llevar un id RESERVADO, ni repetirse, ni venir en blanco.
// Devuelve el PRIMER fallo como un 400 estructurado (mismo `zodItemError` que el
// resto del paquete), con la propiedad apuntando al índice concreto —
// `ticket_types.2.id` — para que el panel sepa qué fila señalar.
//
// El dashboard ya lo valida con zod (`modmailTicketTypeSchema`), pero eso es
// validación de CLIENTE: cualquiera con un token llega al PATCH sin pasar por el
// panel. Y las consecuencias no son cosméticas:
//
//   - un tipo real que robe "none" haría que TODO el histórico sin clasificar
//     (que usa ese id a propósito) empezase a resolver a ese tipo, y lo mismo
//     "contact" con los tickets que abre el staff;
//   - dos tipos con el mismo id hacen ambiguo el lookup por id, así que la
//     etiqueta que se muestra depende del orden del array.
//
// Nil (campo ausente en el PATCH) es válido: no se toca la lista. Una lista
// VACÍA también, y significa "sin tipos" (el flujo directo).
func ValidateModmailTicketTypes(types []dbguild.ModmailTicketType) *apierrors.CustomError {
	seen := make(map[string]int, len(types))
	for i, t := range types {
		property := fmt.Sprintf("ticket_types.%d.id", i)
		if t.ID == "" {
			return zodItemError("Too small: expected string to have >=1 characters", property)
		}
		if dbmodmailticket.IsReservedTicketTypeID(t.ID) {
			return zodItemError(
				fmt.Sprintf("%q está reservado y no puede usarse como id de un tipo de ticket real", t.ID),
				property)
		}
		if first, dup := seen[t.ID]; dup {
			return zodItemError(
				fmt.Sprintf("el id %q está duplicado (ya lo usa ticket_types.%d)", t.ID, first),
				property)
		}
		seen[t.ID] = i
	}
	return nil
}

package dbguild

import (
	"go.mongodb.org/mongo-driver/v2/bson"
)

// This file mirrors the `DBModuleModeration` family in
// `libraries/library-shared/src/db/schemas/DBGuildSchemas.ts`. The field
// ORDER of every struct matches the corresponding zod object schema in
// `apis/api-db/src/domain/zod-schemas/mongo/guild-schema.ts` (which happens to
// match the TS interface order): the Node GET response is produced by
// `moduleModerationSchema.parse(...)`, which normalises key order to the
// schema-definition order — so matching that order keeps the JSON body
// byte-for-byte identical.
//
// The moderation module is per-guild moderation CONFIG only (command mode +
// per-command access/DM, the hybrid-mute strategy, the mod-log channel, the
// AutoMod ruleset and — from v3 — the protection / escalation / effects / raid
// / gate / antinuke / lockdown blocks). The concrete sanctions (infractions)
// live in Postgres (`moderation.infractions`), NOT here.
//
// Nullable fields (`string | null` in TS) use pointer types so JSON encoding
// emits `null` (not `""`) for the unset variant: `log_channel_id`,
// `mute.role_id`, each command's `dm_embed.color`, and the v3
// `raid.alert_*`/`gate.alert_channel_id`/`antinuke.alert_*`. Collection fields
// (`[]string`, `Record<...>`) are never `omitempty`: a present-but-empty value
// must serialise as `[]` / `{}`, never `null`. `NormalizeModeration` backfills
// nil collections so the invariant holds for docs decoded from Mongo/Redis.
//
// Los defaults viven en ESTE paquete (y no en `mocks`) por dos razones: el
// paquete `mocks` ya importa `dbguild`, así que la migración no podría llamarlo
// sin ciclo; y así el seed del documento nuevo y el backfill del documento
// viejo comparten UNA sola fuente de verdad. Mismo patrón que
// `DefaultMusicCommands`.

// ModerationCommandMode mirrors `ModerationCommandMode` (`"slash" | "prefix" |
// "both"`) — how the moderation commands may be invoked (same pattern as
// tempvoice).
type ModerationCommandMode string

const (
	ModerationCommandModeSlash  ModerationCommandMode = "slash"
	ModerationCommandModePrefix ModerationCommandMode = "prefix"
	ModerationCommandModeBoth   ModerationCommandMode = "both"
)

// ModerationMuteMode mirrors `ModerationMuteMode` (`"auto" | "timeout" |
// "role"`) — the hybrid-mute application strategy (native timeout ≤28d / silence
// role).
type ModerationMuteMode string

const (
	ModerationMuteModeAuto    ModerationMuteMode = "auto"
	ModerationMuteModeTimeout ModerationMuteMode = "timeout"
	ModerationMuteModeRole    ModerationMuteMode = "role"
)

// ModerationAccessMode mirrors `DBAccessMode` (`"only" | "all_except"`) — the
// mode of a command access list. `only` = allowlist, `all_except` = denylist.
// Defined locally (not shared with tempvoice) to keep the verticals decoupled,
// matching how tempvoice/modmail each define their own.
