	SchemaVersion int  `bson:"schema_version"       json:"schema_version"`
	Enabled       bool `bson:"enabled"              json:"enabled"`
	// EnabledSince es la fecha de la PRIMERA activación del módulo en este
	// guild — WRITE-ONCE: se estampa al activar por primera vez y no se
	// reescribe nunca (ni al desactivar ni al reactivar). Sostiene el
	// derecho legacy: un guild que activó moderation antes del corte de
	// `globals.module_premium_cutoffs` conserva el módulo entero gratis.
	// `nil` (campo ausente en Mongo) = nunca activado.
	EnabledSince       *JSONDate                    `bson:"enabled_since,omitempty" json:"enabled_since"`
	CommandMode        ModerationCommandMode        `bson:"command_mode"         json:"command_mode"`
	CommandsGlobal     ModerationCommandAccess      `bson:"commands_global"      json:"commands_global"`
	Commands           map[string]ModerationCommand `bson:"commands"             json:"commands"`
	Mute               ModerationMute               `bson:"mute"                 json:"mute"`
	LogChannelID       *string                      `bson:"log_channel_id"       json:"log_channel_id"`
	TrackNativeActions bool                         `bson:"track_native_actions" json:"track_native_actions"`
	Automod            ModerationAutomod            `bson:"automod"              json:"automod"`
	Protection         ModerationProtection         `bson:"protection"           json:"protection"`
	Escalation         ModerationEscalation         `bson:"escalation"           json:"escalation"`
	Effects            ModerationEffects            `bson:"effects"              json:"effects"`
	Raid               ModerationRaid               `bson:"raid"                 json:"raid"`
	Gate               ModerationGate               `bson:"gate"                 json:"gate"`
	Antinuke           ModerationAntinuke           `bson:"antinuke"             json:"antinuke"`
	Lockdown           ModerationLockdown           `bson:"lockdown"             json:"lockdown"`
	// Flows son los flujos de moderación configurables desde el constructor
	// visual (v4). NUNCA `omitempty`: una lista vacía serializa `[]`, jamás
	// `null` — mismo criterio que `Automations`.
	Flows     []ModerationFlow `bson:"flows"                json:"flows"`
	UpdatedAt JSONDate         `bson:"updated_at"           json:"updated_at"`
}

// ── Defaults ────────────────────────────────────────────────────────────────

// AutomodDefaultTimeoutMs es la duración por defecto del tempmute (5 minutos)
// que se aplica cuando la acción de una regla es `delete_timeout`.
const AutomodDefaultTimeoutMs = 5 * 60 * 1000

// ModerationCommandNames es el catálogo de comandos configurables del módulo,
// en orden de dominio: primero los 12 del v2 (sanciones + historial) y después
// los 11 que llegan con el v3 (canal, voz, casos, raid). El seed del documento
// nuevo y el backfill de un documento viejo recorren esta misma lista, así que
// añadir un comando aquí lo siembra en AMBOS caminos.
var ModerationCommandNames = []string{
	"ban",
	"tempban",
	"unban",
	"kick",
	"mute",
	"tempmute",
	"unmute",
	"avisar",
	"infrs",
	"modinf",
	"delinf",
	"delinfs",
	// v3
	"limpiar",
	"lock",
	"unlock",
	"slowmode",
	"vcmute",
	"vcunmute",
	"vcexpulsar",
	"mover",
	"nota",
	"caso",
	"raid",
}

// ModerationAccessDefault es el acceso SIN restricciones en los tres ejes
// (`all_except []`). A diferencia de tempvoice NO siembra el centinela de canal
// temporal: los comandos de moderación funcionan en cualquier canal por
// defecto, y restringir es opt-in desde la dashboard. Slices frescos en cada
// llamada.
func ModerationAccessDefault() ModerationCommandAccess {
	return ModerationCommandAccess{
		Roles:      ModerationAccessList{Mode: ModerationAccessAllExcept, IDs: []string{}},
		Channels:   ModerationAccessList{Mode: ModerationAccessAllExcept, IDs: []string{}},
		Categories: ModerationAccessList{Mode: ModerationAccessAllExcept, IDs: []string{}},
	}
}

// ModerationCommandDefault es un comando activo, heredando el acceso global,
// con aviso por DM y mensaje VACÍO (el módulo cae en su texto por defecto y la
// dashboard lo enseña como placeholder gris — estilo modmail). `dm_embed.color`
// nace `null`.
func ModerationCommandDefault() ModerationCommand {
	return ModerationCommand{
		Enabled:   true,
		UseGlobal: true,
		Access:    ModerationAccessDefault(),
		Aliases:   []string{},
		DmEnabled: true,
		DmEmbed:   ModerationDmEmbed{Content: "", Color: nil},
	}
}

// DefaultModerationCommands siembra `ModerationCommandNames` con el comando por
// defecto. Map y slices frescos en cada llamada, para que quien mute el
// resultado no contamine otros documentos.
func DefaultModerationCommands() map[string]ModerationCommand {
	out := make(map[string]ModerationCommand, len(ModerationCommandNames))
	for _, name := range ModerationCommandNames {
		out[name] = ModerationCommandDefault()
	}
	return out
}

