70	// Set returns the BSON document for the `$set` payload. Returns nil when
71	// no fields were supplied so the repository can short-circuit and avoid
72	// issuing a no-op update.
73	func (b UpdateModuleMusicBody) Set() map[string]any {
74		out := map[string]any{}
75		if b.SchemaVersion != nil {
76			out["schema_version"] = *b.SchemaVersion
77		}
78		if b.Enabled != nil {
79			out["enabled"] = *b.Enabled
80		}
81		if b.MaxSongDuration != nil {
82			out["max_song_duration"] = *b.MaxSongDuration
83		}
84		if b.Loop != nil {
85			out["loop"] = string(*b.Loop)
86		}
87		if b.Volume != nil {
88			out["volume"] = *b.Volume
89		}
90		if b.RadioMode != nil {
91			out["radio_mode"] = *b.RadioMode
92		}
93		if b.MessageRetention != nil {
94			out["message_retention"] = *b.MessageRetention
95		}
