100			out["voice_status_enabled"] = *b.VoiceStatusEnabled
101		}
102		if b.BotPoolEnabled != nil {
103			out["bot_pool_enabled"] = *b.BotPoolEnabled
104		}
105		if b.EnhancedSearch != nil {
106			out["enhanced_search"] = *b.EnhancedSearch
107		}
108		if b.AutoDeleteCommands != nil {
109			// Puntero + slice no vacío garantizado: el puntero distingue "no viene
110			// en el PATCH" de "viene la lista vacía", que es un ajuste legítimo
111			// ("no limpiar nada") y tiene que poder guardarse.
112			list := *b.AutoDeleteCommands
113			if list == nil {
114				list = []string{}
115			}
116			out["auto_delete_commands"] = list
117		}
118		if b.AudioQuality != nil {
119			out["audio_quality"] = string(*b.AudioQuality)
120		}
121		if b.CommandsGlobal != nil {
122			out["commands_global"] = *b.CommandsGlobal
123		}
124		if b.Commands != nil {
125			out["commands"] = *b.Commands
126		}
127		if b.TextChannels != nil {
128			out["text_channels"] = *b.TextChannels
129		}
130		if b.VoiceChannels != nil {
131			out["voice_channels"] = *b.VoiceChannels
132		}
133		if b.DJ != nil {
134			out["dj"] = *b.DJ
135		}
136		if b.RecommendedArtists != nil {
137			out["recommended_artists"] = *b.RecommendedArtists
138		}
139		if len(out) == 0 {
140			return nil
141		}
142		return out
143	}
