package handlers

import (
	"bytes"
	"encoding/json"
	"strconv"

	"github.com/gofiber/fiber/v3"

	"kena.bot/api-db-go/internal/domain/dbguild"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
	"kena.bot/api-db-go/internal/domain/validations"
	"kena.bot/api-db-go/internal/infrastructure/mongorepo"
	"kena.bot/api-db-go/internal/shared/result"
)

// sourceDetailModerationDBNotFound is the source detail stamped on the PATCH
// not-found envelope (the repo returns a bare nil there, so the handler has no
// Sourced to read it from). Kept in step with
// `mongo.SourceDetailModuleModerationDB` — the handler can't import the mongo
// infra package without a layering violation, so the string is duplicated
// locally, à la `sourceDetailGiveawayDBNotFound` in module_giveaway_handler.go.
const sourceDetailModerationDBNotFound = "mongo.guild.module_moderation"

// ModuleModerationHandler wires the two moderation endpoints behind a single
// struct.
//
// Mirrors `module-moderation-controller.ts` (the guild-scoped GET/PATCH).
//
// The result payload is `*dbguild.ModuleModeration` (pointer) so the not-found
// paths can emit `"data":null` — matching the Node controller, whose GET / PATCH
// not-found branches run `applySourceAndStash(sourced{data:null})` before
// throwing MODULE_NOT_FOUND (same as modmail/tempvoice/giveaway, tighter than the
// greeter/logs/music value-payload handlers).
//
// DELIBERATE DIVERGENCE from the Node controller (consistent with the
// greeter/modmail/tempvoice/giveaway mold, which also skips the guild pre-check):
//   - No `GuildRepository.checkGuildExists` → GUILD_NOT_FOUND pre-check on PATCH.
//     A missing guild makes the repo return nil, which the handler maps to
//     MODULE_NOT_FOUND (data:null) — the same not-found signal the update-null
//     branch produces, not GUILD_NOT_FOUND.
type ModuleModerationHandler struct {
	Repo mongorepo.ModuleModerationRepo
}

// NewModuleModerationHandler builds the handler.
func NewModuleModerationHandler(repo mongorepo.ModuleModerationRepo) *ModuleModerationHandler {
	return &ModuleModerationHandler{Repo: repo}
}

// Get mirrors `getModuleModerationController`. Returns the full moderation subdoc
// (default-filled + normalised) with source headers stamped, or a 400
// MODULE_NOT_FOUND with `data:null` + source when the guild has no moderation
// block yet. Honors the optional `?force=true` query that evicts the cache before
// reading (the Node controller parses it via `querySkipCacheValidation` and
// forwards it to `findModule({ force })`).
func (h *ModuleModerationHandler) Get(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleModeration]()
	ctx := c.Context()

	force, _ := strconv.ParseBool(c.Query("force"))

	sourced, err := h.Repo.FindModule(ctx, c.Params("bot_id"), c.Params("guild_id"), force)
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}
	// Stamp the source from the repo even on the not-found path — the FindModule
	// no-document branch still carries "db" / the module detail, mirroring the
	// Node applySourceAndStash(sourced{data:null}).
	if sourced != nil {
		r.SetSource(result.Source(sourced.Source), sourced.SourceDetail)
	}
	if sourced == nil || sourced.Data.SchemaVersion == 0 {
		r.SetData(nil)
		r.AddError(apierrors.MongoMessage("Module not found", apierrors.CodeModuleNotFound))
		return reply(c, r)
	}
	d := sourced.Data
	r.SetData(&d)
	return reply(c, r)
}

// Patch mirrors `patchModuleModerationController`. Strict body
// (DisallowUnknownFields, matching the zod `.strict()`) validates the shape;
// the SAME body is then re-decoded as a raw `map[string]any` so key PRESENCE
// survives, and the repo MergeDeepJSON-merges it into the current subdoc — a
// partial PATCH preserves untouched fields, nested-block siblings, and per-key
// `commands` overrides, and explicit `false`/`0`/`null` leaves are APPLIED
// (mirrors the Node `mergeDeep`, which only skips `undefined`). An empty body
// `{}` is a no-op that still bumps schema_version + updated_at (Node returns
// 200). A missing guild → 400 MODULE_NOT_FOUND with `data:null`.
func (h *ModuleModerationHandler) Patch(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleModeration]()
	ctx := c.Context()

	var body validations.UpdateModuleModerationBody
	dec := json.NewDecoder(bytes.NewReader(c.Body()))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&body); err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	// Re-decode the (already validated) body as a raw map so key presence
	// survives — explicit false/0/null must reach the merge (Node parity).
	patch, err := patchMap(c.Body())
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	sourced, err := h.Repo.Update(ctx, c.Params("bot_id"), c.Params("guild_id"), patch)
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}
	if sourced == nil || sourced.Data.SchemaVersion == 0 {
		// Node's update-null branch stamps db + a source detail + data:null
		// before throwing MODULE_NOT_FOUND. The repo returns a bare nil here,
		// so stamp the source by hand.
		r.SetSource(result.SourceDB, sourceDetailModerationDBNotFound)
		r.SetData(nil)
		r.AddError(apierrors.MongoMessage("Module not found", apierrors.CodeModuleNotFound))
		return reply(c, r)
	}
	d := sourced.Data
	r.SetData(&d)
	r.SetSource(result.Source(sourced.Source), sourced.SourceDetail)
	return reply(c, r)
}

