func TestUpdateModuleMusicBodySet_AllFields(t *testing.T) {
	enabled := true
	radioOn := true
	commandsGlobal := dbguild.MusicCommandAccessDefault()
	commands := map[string]dbguild.MusicCommand{
		"play": dbguild.MusicConfigurableCommandDefault(),
	}
	body := UpdateModuleMusicBody{
		SchemaVersion:      intPtr(5),
		Enabled:            &enabled,
		MaxSongDuration:    intPtr(3600),
		Loop:               loopPtr(dbguild.MusicLoopSong),
		Volume:             intPtr(50),
		RadioMode:          &dbguild.RadioMode{Enabled: radioOn, ChannelID: "123"},
		MessageRetention:   boolPtr(true),
		PinnedNowPlaying:   boolPtr(true),
		VoiceStatusEnabled: boolPtr(true),
		BotPoolEnabled:     boolPtr(true),
		EnhancedSearch:     boolPtr(true),
		AudioQuality:       audioQualityPtr(dbguild.MusicAudioQualityHifi),
		CommandsGlobal:     &commandsGlobal,
		Commands:           &commands,
		TextChannels:       &dbguild.ChannelsConfig{Exclude: true, ChannelsID: []string{"1", "2"}},
		VoiceChannels:      &dbguild.ChannelsConfig{Exclude: false, ChannelsID: []string{"3"}},
		DJ: &dbguild.DJ{
			Enabled:     true,
			Roles:       []string{"r1"},
			Commands:    []string{"c1"},
			Vote:        true,
			VoteTimeout: 120,
		},
		RecommendedArtists: &[]string{"Bruno Mars"},
	}

	set := body.Set()
	if len(set) != 18 {
		t.Fatalf("set has %d fields, want 18", len(set))
	}
	if set["schema_version"] != 5 {
		t.Fatalf("schema_version = %v, want 5", set["schema_version"])
	}
	if _, ok := set["commands_global"]; !ok {
		t.Fatalf("commands_global missing from $set")
	}
	if _, ok := set["commands"]; !ok {
		t.Fatalf("commands missing from $set")
	}
	if set["enabled"] != true {
		t.Fatalf("enabled = %v, want true", set["enabled"])
	}

