type UpdateModuleModerationBody struct {
	Enabled            *bool                                 `json:"enabled,omitempty"`
	CommandMode        *dbguild.ModerationCommandMode        `json:"command_mode,omitempty"`
	CommandsGlobal     *dbguild.ModerationCommandAccess      `json:"commands_global,omitempty"`
	Commands           *map[string]dbguild.ModerationCommand `json:"commands,omitempty"`
	Mute               *dbguild.ModerationMute               `json:"mute,omitempty"`
	LogChannelID       *string                               `json:"log_channel_id,omitempty"`
	TrackNativeActions *bool                                 `json:"track_native_actions,omitempty"`
	Automod            *dbguild.ModerationAutomod            `json:"automod,omitempty"`
	Protection         *dbguild.ModerationProtection         `json:"protection,omitempty"`
	Escalation         *dbguild.ModerationEscalation         `json:"escalation,omitempty"`
	Effects            *dbguild.ModerationEffects            `json:"effects,omitempty"`
	Raid               *dbguild.ModerationRaid               `json:"raid,omitempty"`
	Gate               *dbguild.ModerationGate               `json:"gate,omitempty"`
	Antinuke           *dbguild.ModerationAntinuke           `json:"antinuke,omitempty"`
	Lockdown           *dbguild.ModerationLockdown           `json:"lockdown,omitempty"`
	Flows              *[]dbguild.ModerationFlow             `json:"flows,omitempty"`
}

// isValidModerationCommandMode/isValidModerationMuteMode check membership in
// the (tiny) enums Go can't express as a union. Mirrors the `z.enum(...)` of
// `moderationSchema` in the dashboard.
func isValidModerationCommandMode(m dbguild.ModerationCommandMode) bool {
	switch m {
	case dbguild.ModerationCommandModeSlash,
		dbguild.ModerationCommandModePrefix,
		dbguild.ModerationCommandModeBoth:
		return true
	}
	return false
}

func isValidModerationMuteMode(m dbguild.ModerationMuteMode) bool {
	switch m {
	case dbguild.ModerationMuteModeAuto,
		dbguild.ModerationMuteModeTimeout,
		dbguild.ModerationMuteModeRole:
		return true
	}
	return false
}

// ValidateUpdateModuleModeration cierra el hueco de negocio que sólo cubría el
// zod de la dashboard (`moderationSchema` + `moderationDependencies` en
// `moderation-schema.ts`): un PATCH directo con la credencial de api-db no
// pasa por ahí y no tenía nada que lo parase.
//
// A propósito NO repite aquí las reglas que el propio zod del dashboard
// documenta como degradables (canal de aviso ausente en raid/gate/antinuke,
// escalado activado sin peldaños, listas vacías…): todas caen a un default
// seguro y bloquear el guardado por ellas sería el mismo guard falso que se
// quitó de tempvoice. Sólo se rechaza — o normaliza — lo que el bot
// literalmente no puede cumplir:
//
//   - `command_mode`/`mute.mode` son enums cerrados. Un valor `""` explícito
//     no es "sin elegir" (el PATCH es parcial; un puntero nil ya cubre eso) —
//     es una elección vacía que el bot no reconoce como ninguno de sus modos,
//     así que hace lo mismo que si no hubiera comandos configurados: nada. Y
//     el documento queda con el campo PRESENTE, pareciendo configurado. Se
//     normaliza al default de fábrica ("both"/"auto"), igual que ya hace
//     `MigrateModerationRaw` en lectura para los documentos legacy. Cualquier
//     otro valor que no sea uno de los enumerados es basura irrecuperable: se
//     rechaza.
//   - `mute.mode: "role"` sin `mute.role_id` es una config imposible: el bot
//     no tiene qué rol aplicar. `moderationDependencies` ya bloquea esto en el
//     dashboard; aquí es la única puerta de atrás que faltaba.
func ValidateUpdateModuleModeration(body *UpdateModuleModerationBody) *apierrors.CustomError {
	if body.CommandMode != nil {
		if *body.CommandMode == "" {
			both := dbguild.ModerationCommandModeBoth
			body.CommandMode = &both
		} else if !isValidModerationCommandMode(*body.CommandMode) {
			return zodItemError(
				`Invalid option: expected one of "slash"|"prefix"|"both"`,
				"command_mode",
			)
		}
	}

	if body.Mute != nil {
		if body.Mute.Mode == "" {
			body.Mute.Mode = dbguild.ModerationMuteModeAuto
		} else if !isValidModerationMuteMode(body.Mute.Mode) {
			return zodItemError(
				`Invalid option: expected one of "auto"|"timeout"|"role"`,
				"mute.mode",
			)
		}
		if body.Mute.Mode == dbguild.ModerationMuteModeRole && body.Mute.RoleID == nil {
			return zodItemError(
				"mute.mode \"role\" no puede guardarse sin mute.role_id: el bot no tiene qué rol aplicar",
				"mute.role_id",
			)
		}
	}

	return nil
}

